const NotificationsScreen: React.FC = () => {
  const [activeTab, setActiveTab] = useState<"all" | "budget" | "payment" | "system">("all");
  const tabs = ["all", "budget", "payment", "system"] as const;
  const days = ["Today", "Yesterday"] as const;

  const filtered =
    activeTab === "all"
      ? NOTIFICATIONS
      : NOTIFICATIONS.filter((n) => n.type === activeTab);

  return (
    <div className="p-4">
      {/* Tab pills */}
      <div className="flex gap-2 flex-wrap mb-4">
        {tabs.map((tab) => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className={`px-3 py-1 rounded-full text-xs font-medium capitalize transition-colors ${
              activeTab === tab
                ? "bg-emerald-500 text-white"
                : "bg-gray-100 text-gray-500 hover:bg-gray-200"
            }`}
          >
            {tab}
          </button>
        ))}
      </div>

      {days.map((day) => {
        const dayItems = filtered.filter((n) => n.day === day);
        if (!dayItems.length) return null;
        return (
          <div key={day}>
            <p className="text-xs font-semibold uppercase tracking-wider text-gray-400 mb-2">
              {day}
            </p>
            <div className="bg-white border border-gray-100 rounded-xl px-4 mb-4 divide-y divide-gray-50">
              {dayItems.map((n) => (
                <div key={n.id} className="flex gap-3 py-3">
                  <span
                    className="w-2.5 h-2.5 rounded-full shrink-0 mt-1.5"
                    style={{ background: n.color }}
                  />
                  <div>
                    <p className="text-sm font-medium text-gray-800">
                      {n.icon} {n.title}
                    </p>
                    <p className="text-xs text-gray-500 mt-0.5 leading-relaxed">{n.body}</p>
                    <p className="text-xs text-gray-300 mt-1">{n.time}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        );
      })}

      {filtered.length === 0 && (
        <p className="text-center text-sm text-gray-400 py-8">No notifications.</p>
      )}
    </div>
  );
};

